// 8. Collapsible Sidebar Groups Tree Builders
function loadSavedFilters() {
  const saved = safeGetItem("aiq_saved_filters");
  return saved ? JSON.parse(saved) : [];
}

function starCurrentSearch() {
  const query = (document.getElementById("searchInput").value || "").trim();
  if (!query) {
    alert("Please type a search query first to star it.");
    return;
  }
  const name = prompt("Enter a name for this starred filter:", query);
  if (!name) return;

  const savedFilters = loadSavedFilters();
  if (savedFilters.some(f => f.query === query)) {
    alert("This exact search query is already starred.");
    return;
  }

  savedFilters.push({
    id: "filter_" + Date.now(),
    name: name.trim(),
    query: query
  });
  safeSetItem("aiq_saved_filters", JSON.stringify(savedFilters));
  
  renderSidebarGroups();
  alert(`Starred filter "${name}" saved!`);
}

function deleteSavedFilter(event, id) {
  event.stopPropagation();
  let savedFilters = loadSavedFilters();
  savedFilters = savedFilters.filter(f => f.id !== id);
  safeSetItem("aiq_saved_filters", JSON.stringify(savedFilters));
  renderSidebarGroups();
}

// ── renderSidebarGroups dirty guard ─────────────────────────────────────────
// Called from handleSearch (every debounced keystroke), refreshUIState (every
// 60 s auto-sync), setFilter, and tab renders. Each call previously rebuilt the
// entire sidebar DOM with O(customers × systems) complexity. Stamp guard skips
// when nothing has actually changed.
let _sidebarStamp = null;

function renderSidebarGroups() {
  const container = document.getElementById("sidebarGroupsList");
  if (!container) return;

  // Build a lightweight snapshot of everything the sidebar renders
  const _stamp = `${state.systems.length}|${state.watchlists.length}|${state.groups.length}|${state.activeFilterType}|${state.activeFilterValue || ''}|${state.activeSearchQuery || ''}`;
  if (_stamp === _sidebarStamp) return; // nothing to redraw
  _sidebarStamp = _stamp;

  container.innerHTML = "";

  // 1. Watchlists (Fetched from Active IQ API or Mocked)
  if (state.watchlists && state.watchlists.length > 0) {
    const wlHeader = document.createElement("div");
    wlHeader.className = "tree-section-header";
    wlHeader.innerText = "Active IQ Watchlists";
    container.appendChild(wlHeader);

    state.watchlists.forEach(wl => {
      const item = document.createElement("div");
      item.className = "tree-item";
      if (state.activeFilterType === "WATCHLIST" && state.activeFilterValue === wl.id) {
        item.classList.add("active");
      }
      item.onclick = (e) => {
        e.stopPropagation();
        setFilter("WATCHLIST", wl.id);
      };

      const wlSystems = state.systems.filter(s => wl.systemSerials.includes(s.serialNumber));
      const riskCount = wlSystems.reduce((acc, s) => acc + s.risks.length, 0);
      const badge = riskCount > 0 ? `<span class="tree-badge ${wlSystems.some(s => s.status === 'critical') ? 'critical' : 'warning'}">${riskCount}</span>` : '';

      item.innerHTML = `
        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="margin-right: 8px;"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"></polygon></svg>
        <span class="tree-text">${wl.name}</span>
        <div style="display: flex; gap: 4px; align-items: center; flex-shrink: 0; position: relative; z-index: 10;">
          ${badge}
        </div>
      `;
      container.appendChild(item);
    });
  }

  // 2. Group by Customers (calculated dynamically)
  const customers = [...new Set(state.systems.map(s => s.customerName))].filter(Boolean).sort((a, b) => a.localeCompare(b));
  
  if (customers.length > 0) {
    const custHeader = document.createElement("div");
    custHeader.className = "tree-section-header";
    custHeader.style.marginTop = "16px";
    custHeader.innerText = "Customer Accounts";
    container.appendChild(custHeader);

    customers.forEach(cust => {
      const item = document.createElement("div");
      item.className = "tree-item";
      if (state.activeFilterType === "CUSTOMER" && state.activeFilterValue === cust) {
        item.classList.add("active");
      }
      item.onclick = (e) => {
        e.stopPropagation();
        setFilter("CUSTOMER", cust);
      };
      
      // Calculate active risks for badge
      const custSystems = state.systems.filter(s => s.customerName === cust);
      const riskCount = custSystems.reduce((acc, s) => acc + s.risks.length, 0);
      const badge = riskCount > 0 ? `<span class="tree-badge ${custSystems.some(s => s.status === 'critical') ? 'critical' : 'warning'}">${riskCount}</span>` : '';
      
      const caseCount = custSystems.reduce((acc, s) => acc + (s.supportCases ? s.supportCases.length : 0), 0);
      const caseBadge = caseCount > 0 ? `<span class="tree-badge info" style="background: var(--status-info); cursor: pointer;" onclick="navigateToSupportCases('CUSTOMER', '${cust}', event)" data-tooltip="Click to view all ${caseCount} open support cases">✉ ${caseCount}</span>` : '';

      item.innerHTML = `
        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="margin-right: 8px;"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"></path><circle cx="9" cy="7" r="4"></circle><path d="M23 21v-2a4 4 0 0 0-3-3.87"></path><path d="M16 3.13a4 4 0 0 1 0 7.75"></path></svg>
        <span class="tree-text">${cust}</span>
        <div style="display: flex; gap: 4px; align-items: center; flex-shrink: 0; position: relative; z-index: 10;">
          ${caseBadge}
          ${badge}
        </div>
      `;
      container.appendChild(item);
    });
  }

  // 3. Custom User Defined Groups
  if (state.groups.length > 0) {
    const groupHeader = document.createElement("div");
    groupHeader.className = "tree-section-header";
    groupHeader.style.marginTop = "16px";
    groupHeader.innerText = "Custom Subgroups";
    container.appendChild(groupHeader);

    state.groups.forEach(grp => {
      const item = document.createElement("div");
      item.className = "tree-item";
      if (state.activeFilterType === "GROUP" && state.activeFilterValue === grp.id) {
        item.classList.add("active");
      }
      item.onclick = (e) => {
        e.stopPropagation();
        setFilter("GROUP", grp.id);
      };

      const groupSystems = state.systems.filter(s => grp.systemSerials.includes(s.serialNumber));
      const riskCount = groupSystems.reduce((acc, s) => acc + s.risks.length, 0);
      const badge = riskCount > 0 ? `<span class="tree-badge ${groupSystems.some(s => s.status === 'critical') ? 'critical' : 'warning'}">${riskCount}</span>` : '';

      const caseCount = groupSystems.reduce((acc, s) => acc + (s.supportCases ? s.supportCases.length : 0), 0);
      const caseBadge = caseCount > 0 ? `<span class="tree-badge info" style="background: var(--status-info); cursor: pointer;" onclick="navigateToSupportCases('GROUP', '${grp.id}', event)" data-tooltip="Click to view all ${caseCount} open support cases">✉ ${caseCount}</span>` : '';

      item.innerHTML = `
        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="margin-right: 8px;"><path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z"></path></svg>
        <span class="tree-text">${grp.name}</span>
        <div style="display: flex; gap: 4px; align-items: center; flex-shrink: 0; position: relative; z-index: 10;">
          ${caseBadge}
          ${badge}
        </div>
      `;
      container.appendChild(item);
    });
  }

  // 4. Starred & Dynamic Filters
  const savedFilters = loadSavedFilters();
  if (savedFilters.length > 0) {
    const filterHeader = document.createElement("div");
    filterHeader.className = "tree-section-header";
    filterHeader.style.marginTop = "16px";
    filterHeader.innerText = "Starred Filters (Dynamic)";
    container.appendChild(filterHeader);

    savedFilters.forEach(f => {
      const item = document.createElement("div");
      item.className = "tree-item";
      if (state.activeSearchQuery === f.query) {
        item.classList.add("active");
      }
      
      item.innerHTML = `
        <span style="color: var(--status-warning); margin-right: 8px; font-size: 0.85rem;">★</span>
        <span class="tree-text" title="Query: ${f.query}">${f.name}</span>
        <button class="action-btn secondary delete-filter-btn" style="opacity: 0.6; padding: 2px 6px; font-size: 0.65rem; border-color: transparent; margin-left: auto; background: transparent; color: var(--status-critical);" onclick="deleteSavedFilter(event, '${f.id}')" data-tooltip="Delete this starred filter shortcut.">×</button>
      `;
      
      item.onclick = (e) => {
        document.getElementById("searchInput").value = f.query;
        state.activeSearchQuery = f.query;
        renderOverviewTable();
        renderSidebarGroups();
        renderCharts();
      };
      container.appendChild(item);
    });
  }
}

function copyToClipboard(text, event) {
  if (event) event.stopPropagation();
  navigator.clipboard.writeText(text).then(() => {
    showToast("Copied to clipboard: " + text);
  }).catch(err => {
    console.error("Failed to copy: ", err);
  });
}

function showToast(message, type = 'success') {
  const colors = {
    success: { bg: 'rgba(0,230,118,0.95)',   text: '#000', shadow: 'rgba(0,230,118,0.2)'   },
    info:    { bg: 'rgba(0,200,255,0.92)',   text: '#000', shadow: 'rgba(0,200,255,0.2)'   },
    error:   { bg: 'rgba(255,51,102,0.95)',  text: '#fff', shadow: 'rgba(255,51,102,0.25)' },
  };
  const c = colors[type] || colors.success;

  let toast = document.getElementById("toastNotification");
  if (!toast) {
    toast = document.createElement("div");
    toast.id = "toastNotification";
    toast.style.position = "fixed";
    toast.style.bottom = "20px";
    toast.style.right = "20px";
    toast.style.padding = "10px 20px";
    toast.style.borderRadius = "4px";
    toast.style.fontWeight = "600";
    toast.style.fontSize = "0.85rem";
    toast.style.zIndex = "9999";
    toast.style.transition = "opacity 0.3s ease, background-color 0.2s ease";
    document.body.appendChild(toast);
  }
  toast.style.backgroundColor = c.bg;
  toast.style.color            = c.text;
  toast.style.boxShadow        = `0 4px 12px ${c.shadow}`;
  toast.innerText = message;
  toast.style.opacity = "1";
  toast.style.display = "block";
  setTimeout(() => {
    toast.style.opacity = "0";
    setTimeout(() => { toast.style.display = "none"; }, 300);
  }, type === 'error' ? 4000 : 2500);
}


function setFilter(type, value) {
  state.activeFilterType = type;
  state.activeFilterValue = value;
  state.selectedSAMSystemSerial = "ALL";
  state.selectedCSMSystemSerial = "ALL";
  
  // Context-aware update: stay on the current tab but refresh system list scope
  switchTab(state.currentTab);
  
  renderSidebarGroups();
}

function navigateToSupportCases(type, value, event) {
  if (event) {
    event.stopPropagation();
    event.preventDefault();
  }
  
  if (type === "SYSTEM") {
    const sys = state.systems.find(s => s.serialNumber === value);
    if (sys) {
      state.currentTab = "sam";
      setFilter("CUSTOMER", sys.customerName);
      state.selectedSAMSystemSerial = value;
      switchTab("sam");
    }
  } else if (type === "CUSTOMER") {
    state.currentTab = "sam";
    setFilter("CUSTOMER", value);
    switchTab("sam");
  } else if (type === "GROUP") {
    state.currentTab = "sam";
    setFilter("GROUP", value);
    switchTab("sam");
  }
}

function resetFilter() {
  state.activeFilterType = "ALL";
  state.activeFilterValue = "";
  state.activeSearchQuery = "";
  state.activeKpiFilter = "NONE";
  state.selectedSAMSystemSerial = "ALL";
  state.selectedCSMSystemSerial = "ALL";
  
  // Clear KPI card active classes
  const cards = ["kpiCardAll", "kpiCardCritical", "kpiCardWarning", "kpiCardContract"];
  cards.forEach(id => {
    const el = document.getElementById(id);
    if (el) el.classList.remove("active");
  });

  const searchInput = document.getElementById("searchInput");
  if (searchInput) searchInput.value = "";
  switchTab(state.currentTab);
  renderSidebarGroups();
}

function resetFilterAndGoToOverview() {
  state.activeFilterType = "ALL";
  state.activeFilterValue = "";
  state.activeSearchQuery = "";
  state.activeKpiFilter = "NONE";
  state.selectedSAMSystemSerial = "ALL";
  state.selectedCSMSystemSerial = "ALL";
  
  const cards = ["kpiCardAll", "kpiCardCritical", "kpiCardWarning", "kpiCardContract"];
  cards.forEach(id => {
    const el = document.getElementById(id);
    if (el) el.classList.remove("active");
  });

  const searchInput = document.getElementById("searchInput");
  if (searchInput) searchInput.value = "";
  switchTab("overview");
  renderSidebarGroups();
}

// 9. Custom Group & Metadata Editor Logic (in Settings panel)
// 9. Custom Group & Metadata Editor Logic (in Settings panel)
function editCustomGroup(groupId) {
  const grp = state.groups.find(g => g.id === groupId);
  if (!grp) return;
  
  state.editingGroupId = groupId;
  document.getElementById("subgroupFormTitle").innerText = "Edit Custom Subgroup";
  document.getElementById("newGroupNameInput").value = grp.name;
  
  document.querySelectorAll(".group-system-checkbox").forEach(chk => {
    chk.checked = grp.systemSerials.includes(chk.value);
  });
  
  document.getElementById("saveSubgroupBtn").innerText = "Update Subgroup";
  document.getElementById("cancelSubgroupEditBtn").style.display = "inline-block";
}

function cancelSubgroupEdit() {
  state.editingGroupId = null;
  document.getElementById("subgroupFormTitle").innerText = "Create Custom Subgroup";
  document.getElementById("newGroupNameInput").value = "";
  document.querySelectorAll(".group-system-checkbox").forEach(chk => chk.checked = false);
  document.getElementById("saveSubgroupBtn").innerText = "Create Subgroup";
  document.getElementById("cancelSubgroupEditBtn").style.display = "none";
}

function createNewSystemPrompt() {
  const serial = prompt("Enter Serial Number for New System:");
  if (!serial) return;
  const serialClean = serial.trim();
  if (state.systems.some(s => s.serialNumber === serialClean)) {
    alert("A system with this serial number already exists!");
    return;
  }
  const name = prompt("Enter System Name:", "new-system-" + serialClean);
  if (!name) return;
  const customer = prompt("Enter Customer Account Name:", "Default Customer");
  if (!customer) return;

  const newSys = {
    serialNumber: serialClean,
    systemName: name.trim(),
    customerName: customer.trim(),
    clusterName: "cluster-" + name.trim(),
    platform: "FAS2750",
    ontapVersion: "ONTAP 9.12.1",
    status: "normal",
    risks: [],
    upgrades: { targetVersion: "Up to Date", urgency: "none", benefits: "Running recommended release." },
    contracts: { endDate: "2027-12-31", daysRemaining: 500, status: "normal", supportLevel: "Core Support" },
    fieldActions: [],
    hypervisors: [],
    securityBulletins: [],
    supportCases: [],
    logistics: { deliveryAddress: "Site HQ", accessRestrictions: "Standard Business Hours", shippingAlert: "None" },
    contacts: { name: "John Doe", phone: "555-0100", email: "johndoe@example.com", nssUsername: "jdoe" },
    salesHealth: { accountManager: "Account Rep", supportTam: "TAM Rep", sentimentScore: 9.0, healthStatus: "Stable", upsellPotential: "None", refreshWindow: "Q4 2027" },
    projections: { growthRateGBPerDay: 50, daysToLimit: 365, limitDate: "2027-07-06" },
    efficiency: { ratio: "2.4:1" }
  };

  state.systems.push(newSys);
  saveSystems();
  populateSystemSelectors();
  updateSearchSuggestions();
  
  document.getElementById("editorSystemSelect").value = serialClean;
  loadSelectedSystemMetadataForEdit();
  
  switchTab(state.currentTab);
  alert(`System "${name.trim()}" (S/N: ${serialClean}) created successfully! Additional specifications can be edited below.`);
}

function deleteCurrentSystem() {
  const select = document.getElementById("editorSystemSelect");
  if (!select || !select.value) return;
  const serial = select.value;
  const found = state.systems.find(s => s.serialNumber === serial);
  if (!found) return;

  if (!confirm(`Are you sure you want to delete system "${found.systemName}" (S/N: ${serial})?`)) {
    return;
  }

  state.systems = state.systems.filter(s => s.serialNumber !== serial);
  state.groups.forEach(g => {
    g.systemSerials = g.systemSerials.filter(sn => sn !== serial);
  });
  deleteSystemMetadataOverride(serial);

  saveSystems();
  populateSystemSelectors();
  updateSearchSuggestions();

  if (state.systems.length > 0) {
    state.selectedSystem = state.systems[0];
    select.value = state.selectedSystem.serialNumber;
    loadSelectedSystemMetadataForEdit();
  } else {
    state.selectedSystem = null;
  }
  
  switchTab(state.currentTab);
  alert("System deleted successfully!");
}

function updateSearchSuggestions() {
  // Legacy - dynamic custom autocomplete dropdown handles this now
}

function updateCustomSearchSuggestions(query) {
  const container = document.getElementById("searchSuggestionsContainer");
  if (!container) return;
  
  const val = query.trim().toLowerCase();
  if (!val) {
    container.style.display = "none";
    return;
  }
  
  const matches = [];
  const seen = new Set();
  
  state.systems.forEach(sys => {
    // Customer
    if (sys.customerName.toLowerCase().includes(val) && !seen.has(`CUST:${sys.customerName}`)) {
      seen.add(`CUST:${sys.customerName}`);
      matches.push({ text: sys.customerName, type: "Customer", value: sys.customerName });
    }
    // System Name
    if (sys.systemName.toLowerCase().includes(val) && !seen.has(`SYS:${sys.systemName}`)) {
      seen.add(`SYS:${sys.systemName}`);
      matches.push({ text: sys.systemName, type: "System", value: sys.systemName });
    }
    // Cluster
    if (sys.clusterName.toLowerCase().includes(val) && !seen.has(`CLUS:${sys.clusterName}`)) {
      seen.add(`CLUS:${sys.clusterName}`);
      matches.push({ text: sys.clusterName, type: "Cluster", value: sys.clusterName });
    }
    // Serial
    if (sys.serialNumber.toLowerCase().includes(val) && !seen.has(`SER:${sys.serialNumber}`)) {
      seen.add(`SER:${sys.serialNumber}`);
      matches.push({ text: sys.serialNumber, type: "Serial Number", value: sys.serialNumber });
    }
  });
  
  if (matches.length === 0) {
    container.style.display = "none";
    return;
  }
  
  container.innerHTML = "";
  matches.slice(0, 8).forEach(match => {
    const div = document.createElement("div");
    div.className = "custom-autocomplete-item";
    div.innerHTML = `
      <span>${match.text}</span>
      <span class="type-badge">${match.type}</span>
    `;
    div.onclick = (e) => {
      e.stopPropagation();
      const searchInput = document.getElementById("searchInput");
      if (searchInput) {
        searchInput.value = match.value;
        state.activeSearchQuery = match.value;
      }
      container.style.display = "none";
      executeSearchGo();
    };
    container.appendChild(div);
  });
  
  container.style.display = "block";
}

function populateGroupManagerSystems() {
  const container = document.getElementById("groupManagerSystemsList");
  if (!container) return;
  container.innerHTML = "";

  state.systems.forEach(sys => {
    const div = document.createElement("div");
    div.style.display = "flex";
    div.style.alignItems = "center";
    div.style.gap = "8px";
    div.style.marginBottom = "8px";
    div.style.fontSize = "0.85rem";

    div.innerHTML = `
      <input type="checkbox" class="group-system-checkbox" value="${sys.serialNumber}" id="chk_${sys.serialNumber}" style="cursor: pointer;">
      <label for="chk_${sys.serialNumber}" style="cursor: pointer;">${sys.systemName} (S/N: ${sys.serialNumber} - ${sys.platform})</label>
    `;
    container.appendChild(div);
  });
  
  // Render existing groups list in settings for deletion & edit
  const listContainer = document.getElementById("settingsGroupsManagerList");
  if (!listContainer) return;
  listContainer.innerHTML = "";
  
  if (state.groups.length === 0) {
    listContainer.innerHTML = `<div style="font-size: 0.8rem; color: var(--text-muted);">No custom subgroups defined.</div>`;
    return;
  }
  
  state.groups.forEach(grp => {
    const item = document.createElement("div");
    item.style.display = "flex";
    item.style.justifyContent = "space-between";
    item.style.alignItems = "center";
    item.style.padding = "8px 12px";
    item.style.background = "rgba(255,255,255,0.01)";
    item.style.border = "1px solid var(--border-color)";
    item.style.borderRadius = "var(--radius-sm)";
    item.style.marginBottom = "6px";
    item.style.fontSize = "0.8rem";

    item.innerHTML = `
      <div>
        <strong>${grp.name}</strong> (${grp.systemSerials.length} systems)
      </div>
      <div style="display: flex; gap: 8px;">
        <button class="action-btn" style="font-size: 0.7rem; padding: 4px 8px; border-color: rgba(0,229,255,0.2);" onclick="editCustomGroup('${grp.id}')" title="Edit this subgroup's name and system assignments.">Edit</button>
        <button class="action-btn secondary" style="font-size: 0.7rem; padding: 4px 8px; color: var(--status-critical); border-color: rgba(255,51,102,0.2);" onclick="deleteCustomGroup('${grp.id}')" title="Delete this subgroup completely (does not delete member systems).">Delete</button>
      </div>
    `;
    listContainer.appendChild(item);
  });
}

function populateLogisticsEditor() {
  const select = document.getElementById("editorSystemSelect");
  if (!select) return;
  
  const originalVal = select.value;
  select.innerHTML = "";
  
  state.systems.forEach(sys => {
    const opt = document.createElement("option");
    opt.value = sys.serialNumber;
    opt.innerText = sys.systemName;
    select.appendChild(opt);
  });
  
  if (originalVal && state.systems.some(s => s.serialNumber === originalVal)) {
    select.value = originalVal;
  }
  
  loadSelectedSystemMetadataForEdit();
}

function loadSelectedSystemMetadataForEdit() {
  const serial = document.getElementById("editorSystemSelect").value;
  const sys = state.systems.find(s => s.serialNumber === serial);
  if (!sys) return;

  const logistics = sys.logistics || { deliveryAddress: "", accessRestrictions: "", shippingAlert: "None" };
  const contacts = sys.contacts || { name: "", phone: "", email: "", nssUsername: "" };
  const health = sys.salesHealth || { accountManager: "", supportTam: "", sentimentScore: 7.0, healthStatus: "Stable", upsellPotential: "", refreshWindow: "Under Review" };
  const proj = sys.projections || { growthRateGBPerDay: 100, daysToLimit: 120, limitDate: "Under Review", peakIops: 10000, avgLatencyMs: 2.5, historicalCapacityMonths: [10, 12, 14, 16, 18, 20], projectedCapacityMonths: [22, 24, 26] };
  const bulletins = sys.securityBulletins || [];
  const cases = sys.supportCases || [];

  // Inject current saved values summary for clear comparison
  const currentSummaryEl = document.getElementById("editorCurrentValuesSummary");
  if (currentSummaryEl) {
    currentSummaryEl.style.display = "block";
    currentSummaryEl.innerHTML = `
      <div style="font-weight: 700; color: var(--accent-cyan); margin-bottom: 6px; text-transform: uppercase; font-size: 0.72rem; letter-spacing: 0.5px;">Current Saved Logistics (Active Database)</div>
      <div style="margin-bottom: 2px;"><strong>Site Address</strong>: <span style="color: var(--text-secondary); font-style: italic;">${logistics.deliveryAddress || '(Not Set)'}</span></div>
      <div style="margin-bottom: 2px;"><strong>Access Rules</strong>: <span style="color: var(--text-secondary);">${logistics.accessRestrictions || '(Not Set)'}</span></div>
      <div style="margin-bottom: 2px;"><strong>Tech Contact</strong>: <span style="color: var(--text-secondary);">${contacts.name || '(Not Set)'} (${contacts.email || 'No email'})</span></div>
    `;
  }

  document.getElementById("editSystemName").value = sys.systemName || "";
  document.getElementById("editSerialNumber").value = sys.serialNumber || "";
  document.getElementById("editCustomerName").value = sys.customerName || "";
  document.getElementById("editClusterName").value = sys.clusterName || "";
  document.getElementById("editPlatform").value = sys.platform || "";
  document.getElementById("editOntapVersion").value = sys.ontapVersion || "";

  document.getElementById("editDeliveryAddress").value = logistics.deliveryAddress;
  document.getElementById("editAccessRestrictions").value = logistics.accessRestrictions;
  document.getElementById("editShippingAlert").value = logistics.shippingAlert;

  document.getElementById("editContactName").value = contacts.name;
  document.getElementById("editContactPhone").value = contacts.phone;
  document.getElementById("editContactEmail").value = contacts.email;
  document.getElementById("editNssUsername").value = contacts.nssUsername;

  document.getElementById("editAccountManager").value = health.accountManager;
  document.getElementById("editSupportTam").value = health.supportTam;
  document.getElementById("editSentimentScore").value = health.sentimentScore;
  document.getElementById("editHealthStatus").value = health.healthStatus;
  document.getElementById("editUpsellPotential").value = health.upsellPotential;
  document.getElementById("editRefreshWindow").value = health.refreshWindow;

  // Set projections fields inside edit panel
  document.getElementById("editGrowthRate").value = proj.growthRateGBPerDay;
  document.getElementById("editDaysToLimit").value = proj.daysToLimit;
  document.getElementById("editLimitDate").value = proj.limitDate;
  document.getElementById("editPeakIops").value = proj.peakIops;
  document.getElementById("editAvgLatency").value = proj.avgLatencyMs;
  document.getElementById("editHistCapacityCSV").value = proj.historicalCapacityMonths.join(",");
  document.getElementById("editProjCapacityCSV").value = proj.projectedCapacityMonths.join(",");

  // Set Security Bulletins JSON
  document.getElementById("editSecurityBulletinsJSON").value = JSON.stringify(bulletins, null, 2);

  // Set Open Support Cases JSON
  document.getElementById("editSupportCasesJSON").value = JSON.stringify(cases, null, 2);
}

function saveSystemMetadata() {
  const serial = document.getElementById("editorSystemSelect").value;
  const idx = state.systems.findIndex(s => s.serialNumber === serial);
  if (idx === -1) return;

  const newSerial = document.getElementById("editSerialNumber").value.trim();
  const newSysName = document.getElementById("editSystemName").value.trim();
  const newCustName = document.getElementById("editCustomerName").value.trim();
  const newClusterName = document.getElementById("editClusterName").value.trim();
  const newPlatform = document.getElementById("editPlatform").value.trim();
  const newOntap = document.getElementById("editOntapVersion").value.trim();

  if (!newSerial || !newSysName || !newCustName) {
    alert("System Name, Serial Number, and Customer Name are required core fields.");
    return;
  }

  // Handle serial number change
  if (newSerial !== serial) {
    if (state.systems.some(s => s.serialNumber === newSerial)) {
      alert(`A system with serial number "${newSerial}" already exists!`);
      return;
    }
    // Update subgroup assignments
    state.groups.forEach(g => {
      g.systemSerials = g.systemSerials.map(sn => sn === serial ? newSerial : sn);
    });
    renameSystemMetadataOverride(serial, newSerial);
  }

  // Store original telemetry parameters to generate difference mapping if modified
  if (!state.systems[idx].originalLogistics) {
    state.systems[idx].originalLogistics = JSON.parse(JSON.stringify(state.systems[idx].logistics || { deliveryAddress: "", accessRestrictions: "", shippingAlert: "None" }));
  }
  if (!state.systems[idx].originalContacts) {
    state.systems[idx].originalContacts = JSON.parse(JSON.stringify(state.systems[idx].contacts || { name: "", phone: "", email: "", nssUsername: "" }));
  }

  state.systems[idx].serialNumber = newSerial;
  state.systems[idx].systemName = newSysName;
  state.systems[idx].customerName = newCustName;
  state.systems[idx].clusterName = newClusterName;
  state.systems[idx].platform = newPlatform;
  state.systems[idx].ontapVersion = newOntap;

  state.systems[idx].logistics = {
    deliveryAddress: document.getElementById("editDeliveryAddress").value.trim(),
    accessRestrictions: document.getElementById("editAccessRestrictions").value.trim(),
    shippingAlert: document.getElementById("editShippingAlert").value.trim()
  };

  state.systems[idx].contacts = {
    name: document.getElementById("editContactName").value.trim(),
    phone: document.getElementById("editContactPhone").value.trim(),
    email: document.getElementById("editContactEmail").value.trim(),
    nssUsername: document.getElementById("editNssUsername").value.trim()
  };

  state.systems[idx].salesHealth = {
    accountManager: document.getElementById("editAccountManager").value.trim(),
    supportTam: document.getElementById("editSupportTam").value.trim(),
    sentimentScore: parseFloat(document.getElementById("editSentimentScore").value || "7.0"),
    healthStatus: document.getElementById("editHealthStatus").value.trim(),
    upsellPotential: document.getElementById("editUpsellPotential").value.trim(),
    refreshWindow: document.getElementById("editRefreshWindow").value.trim()
  };

  // Save projections numbers
  const histCSV = document.getElementById("editHistCapacityCSV").value.trim();
  const projCSV = document.getElementById("editProjCapacityCSV").value.trim();

  state.systems[idx].projections = {
    growthRateGBPerDay: parseInt(document.getElementById("editGrowthRate").value || "100"),
    daysToLimit: parseInt(document.getElementById("editDaysToLimit").value || "120"),
    limitDate: document.getElementById("editLimitDate").value.trim(),
    peakIops: parseInt(document.getElementById("editPeakIops").value || "10000"),
    avgLatencyMs: parseFloat(document.getElementById("editAvgLatency").value || "2.5"),
    historicalCapacityMonths: histCSV ? histCSV.split(",").map(v => parseFloat(v.trim())) : [10, 11, 12, 13, 14, 15],
    projectedCapacityMonths: projCSV ? projCSV.split(",").map(v => parseFloat(v.trim())) : [16, 17, 18]
  };

  // Parse and save security bulletins JSON
  try {
    const rawJSON = document.getElementById("editSecurityBulletinsJSON").value.trim();
    state.systems[idx].securityBulletins = JSON.parse(rawJSON || "[]");
  } catch (err) {
    alert("Invalid Security Bulletins JSON format. Please verify syntax.");
    return;
  }

  // Parse and save open support cases JSON
  try {
    const rawCasesJSON = document.getElementById("editSupportCasesJSON").value.trim();
    state.systems[idx].supportCases = JSON.parse(rawCasesJSON || "[]");
  } catch (err) {
    alert("Invalid Support Cases JSON format. Please verify syntax.");
    return;
  }

  saveSystemMetadataOverride(newSerial, {
    logistics: state.systems[idx].logistics,
    contacts: state.systems[idx].contacts,
    salesHealth: state.systems[idx].salesHealth,
    projections: state.systems[idx].projections
  });

  saveSystems();
  populateSystemSelectors();
  updateSearchSuggestions();

  // If the edited system was the currently selected system, update state.selectedSystem
  if (!state.selectedSystem || state.selectedSystem.serialNumber === serial) {
    state.selectedSystem = state.systems[idx];
  }

  // Re-select in the editor selector
  document.getElementById("editorSystemSelect").value = newSerial;

  // Refresh active tab views
  switchTab(state.currentTab);

  // If action plan is currently visible on screen, regenerate it to reflect changes immediately
  if (document.getElementById("planControlsPanel").style.display === "flex") {
    generateActionPlan();
  }
  alert(`Metadata & specifications for "${newSysName}" updated successfully!`);
}

function handleCreateGroup() {
  const nameInput = document.getElementById("newGroupNameInput");
  const name = nameInput.value.trim();
  if (!name) {
    alert("Please enter a group name.");
    return;
  }

  const selectedSerials = [];
  document.querySelectorAll(".group-system-checkbox:checked").forEach(chk => {
    selectedSerials.push(chk.value);
  });

  if (selectedSerials.length === 0) {
    alert("Please select at least one system to assign to this group.");
    return;
  }

  if (state.editingGroupId) {
    const idx = state.groups.findIndex(g => g.id === state.editingGroupId);
    if (idx !== -1) {
      state.groups[idx].name = name;
      state.groups[idx].systemSerials = selectedSerials;
      saveGroups();
      cancelSubgroupEdit();
      alert("Subgroup updated successfully!");
    }
  } else {
    const newGroup = {
      id: "group_" + Date.now(),
      name: name,
      systemSerials: selectedSerials
    };

    state.groups.push(newGroup);
    saveGroups();
    nameInput.value = "";
    document.querySelectorAll(".group-system-checkbox").forEach(chk => chk.checked = false);
    alert("Group created successfully!");
  }

  populateGroupManagerSystems();
  renderSidebarGroups();
}

function deleteCustomGroup(groupId) {
  state.groups = state.groups.filter(g => g.id !== groupId);
  saveGroups();
  alert("Group deleted successfully.");
  populateGroupManagerSystems();
  renderSidebarGroups();
}

// ── API Diagnostics ───────────────────────────────────────────────────────────
// Probes all key endpoints and shows results in a visible modal (no DevTools needed)
async function runAPIDiagnostics() {
  const { refresh } = loadConfig();
  if (!refresh) {
    alert("No API refresh token found.\n\nPaste your Active IQ refresh token into the field above and click 'Save Configuration', then run diagnostics again.");
    return;
  }

  // Temporarily force mock mode OFF so we always test the real API,
  // regardless of what the toggle currently says or what state.mockMode is.
  const savedMock = state.mockMode;
  state.mockMode  = false;

  const results = [];
  const probe   = async (label, ep, showFullJson = false) => {
    try {
      const t0   = Date.now();
      const data = await callActiveIQAPI(ep);
      const ms   = Date.now() - t0;
      const keys = data && typeof data === "object" ? Object.keys(data) : [];
      let preview = "";
      if (Array.isArray(data))    preview = `Array[${data.length}]${data.length ? ": " + JSON.stringify(data[0]).slice(0,120) : ""}`;
      else if (keys.length > 0) {
        if (showFullJson) {
          // Show the full JSON response for this endpoint
          preview = JSON.stringify(data).slice(0, 600);
        } else {
          const v = data[keys[0]];
          preview = Array.isArray(v)
            ? `{ ${keys[0]}: Array[${v.length}]${v.length ? " → " + JSON.stringify(v[0]).slice(0,100) : ""} }`
            : `{ ${JSON.stringify(data).slice(0, 200)} }`;
        }
      } else { preview = "(empty object — {})" ; }
      results.push({ label, ep, status: "200 OK", ms, preview, ok: true });
    } catch (e) {
      results.push({ label, ep, status: e.message, ms: 0, preview: "", ok: false });
    }
  };

  try {
    const tok = await getValidAccessToken().catch(() => "ERROR");
    results.push({ label: "─── Token ───", ep: "", status: "", ms: 0,
      preview: tok === "ERROR" ? "⚠ Token exchange failed!" : `JWT prefix: ${tok.slice(0,30)}…`, ok: tok !== "ERROR" });


    await probe("Watchlist All",              "/watchlist/all");

    // ── Search System variants ──────────────────────────────────────────────
    await probe("Search v3 system (wildcard)", "/v3/search/system?searchText=*&limit=10");
    await probe("Search v3 system (no text)",  "/v3/search/system?limit=10");
    await probe("Search v2 customer (wild)",   "/v2/search/system/level/customer?searchText=*&limit=10");
    await probe("Search v1 customer (wild)",   "/v1/search/system/level/customer?searchText=*&limit=10");
    await probe("Search v1 watchlist (wild)",  "/v1/search/system/level/watchlist?searchText=*&limit=10");

    // ── Search Aggregate / Parent (returns customer/site IDs) ───────────────
    await probe("v3 Search Aggregate",         "/v3/search/aggregate?searchText=*&limit=10");
    await probe("v3 Search Parent",            "/v3/search/parent?searchText=*&limit=10");
    await probe("v3 Search Location",          "/v3/search/location?searchText=*&limit=10");
    await probe("v3 Count Aggregate",          "/v3/search/count/aggregate");
    await probe("v3 Count Parent",             "/v3/search/count/parent");
    await probe("v1 Aggregate customer",       "/v1/search/aggregate/level/customer?searchText=*&limit=10");
    await probe("v1 Parent customer",          "/v1/search/parent/level/customer?searchText=*&limit=10");
    await probe("v1 Location customer",        "/v1/search/location/level/customer?searchText=*&limit=10");
    await probe("v1 Count Agg customer",       "/v1/search/count/aggregate/level/customer");

    // ── Health ──────────────────────────────────────────────────────────────
    await probe("Health Summary v1 customer",  "/v1/health/summary/level/customer?searchText=*&limit=10");
    await probe("Health Details v1 customer",  "/v1/health/details/level/customer?searchText=*&limit=10");
    await probe("Health Risks v2",             "/v2/health/risks");

    // ── Breadth endpoints (no level/id needed) ──────────────────────────────
    await probe("EoS Details",                 "/eos/details");
    await probe("EoS Contracts Details",       "/eos/contracts/details");
    await probe("Capacity2 Usage",             "/capacity2/usage");
    await probe("Firmware Details",            "/firmware/details");
    await probe("Keystone Customers",          "/keystone/customers");
    await probe("Upgrade Summary (customer)",  "/upgrade/summary/level/customer?searchText=*");

    // ── API Registration & Subscription (show FULL response to see account type) ─
    await probe("API Registration",            "/api/registration",      true);
    await probe("API Subscription",            "/api/catalogSubscription", true);

    // ── GraphQL ──────────────────────────────────────────────────────────────
    // Try GraphQL endpoint (may work even when REST data endpoints fail)
    try {
      const t0  = Date.now();
      const tok = await getValidAccessToken();
      const gqlUrl = `${getEffectiveApiBaseUrl().replace(/\/v\d+$/, "")}/graphql`;
      const gqlRes = await fetch(gqlUrl, {
        method: "POST",
        headers: { "AuthorizationToken": tok, "Content-Type": "application/json", "Accept": "application/json" },
        body: JSON.stringify({ query: "{ __typename }" })
      });
      const ms = Date.now() - t0;
      if (gqlRes.ok) {
        const gqlData = await gqlRes.json();
        results.push({ label: "GraphQL endpoint", ep: gqlUrl, status: `200 OK (${ms}ms)`, preview: JSON.stringify(gqlData).slice(0,200), ok: true });
      } else {
        results.push({ label: "GraphQL endpoint", ep: gqlUrl, status: `HTTP ${gqlRes.status}`, preview: "", ok: false });
      }
    } catch (ge) {
      results.push({ label: "GraphQL endpoint", ep: "/graphql", status: ge.message, preview: "", ok: false });
    }


    // Only probe watchlist-scoped endpoints if we have REAL watchlist IDs
    // (IDs starting with 'wl_' are stale mock data — skip them)
    const realWatchlists = (state.watchlists || []).filter(
      wl => wl.id && !String(wl.id).startsWith("wl_")
    );
    if (realWatchlists.length > 0) {
      results.push({ label: "─── Watchlists ───", ep: "", status: "", ms: 0, preview: `${realWatchlists.length} real watchlist(s) found`, ok: true });
      for (const wl of realWatchlists.slice(0, 3)) {
        await probe(`Search watchlist: ${wl.name}`, `/v1/search/system/level/watchlist?id=${wl.id}&limit=10`);
        await probe(`Health watchlist: ${wl.name}`,  `/health/details/level/watchlist/id/${wl.id}`);
      }
    } else {
      results.push({ label: "─── Watchlists ───", ep: "", status: "", ms: 0,
        preview: "/watchlist/all returned error — no real IDs available. Check error above.", ok: false });
    }


  } finally {
    state.mockMode = savedMock; // Always restore
  }

  showDiagnosticsModal(results);
}


function showDiagnosticsModal(results) {
  // Remove any existing diagnostic modal
  document.getElementById("diagModal")?.remove();

  const rows = results.map(r => {
    const color  = !r.ep ? "#7ee8fa" : r.ok ? "#4ade80" : "#f87171";
    const bg     = !r.ep ? "rgba(126,232,250,0.08)" : "";
    return `<tr style="background:${bg}">
      <td style="padding:4px 8px;color:${color};font-weight:${!r.ep?700:400}">${r.label}</td>
      <td style="padding:4px 8px;color:#94a3b8;font-size:11px;word-break:break-all">${r.ep}</td>
      <td style="padding:4px 8px;color:${color}">${r.status}${r.ms ? " ("+r.ms+"ms)" : ""}</td>
      <td style="padding:4px 8px;color:#cbd5e1;font-size:11px">${r.preview}</td>
    </tr>`;
  }).join("");

  const modal = document.createElement("div");
  modal.id    = "diagModal";
  modal.style.cssText = "position:fixed;inset:0;background:rgba(0,0,0,0.75);z-index:99999;display:flex;align-items:center;justify-content:center";
  modal.innerHTML = `
    <div style="background:#0f1729;border:1px solid #334155;border-radius:12px;padding:24px;max-width:900px;width:95%;max-height:85vh;overflow-y:auto">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px">
        <h3 style="color:#7ee8fa;margin:0;font-size:16px">🔬 API Diagnostics Report</h3>
        <button onclick="document.getElementById('diagModal').remove()" style="background:#1e3a5f;color:#7ee8fa;border:none;border-radius:6px;padding:6px 14px;cursor:pointer">Close</button>
      </div>
      <p style="color:#94a3b8;font-size:12px;margin-bottom:16px">
        Green = data returned. Red = error/empty. Share this table if you need support.
      </p>
      <table style="width:100%;border-collapse:collapse;font-size:12px;font-family:monospace">
        <thead><tr style="color:#475569;border-bottom:1px solid #1e3a5f">
          <th style="text-align:left;padding:4px 8px">Endpoint</th>
          <th style="text-align:left;padding:4px 8px">Path</th>
          <th style="text-align:left;padding:4px 8px">Result</th>
          <th style="text-align:left;padding:4px 8px">Response Shape</th>
        </tr></thead>
        <tbody>${rows}</tbody>
      </table>
    </div>`;
  document.body.appendChild(modal);
}

// 10. Global active status visual indicators & Settings Saves

// ── Multiple Customer Accounts (multi-tenant) manager ──────────────────────
// Lets a TAM/MSP add several separate Active IQ credentials (different
// customers, different logins). Each account syncs independently server-side
// (server.py's _sync_all_accounts) and is merged into one fleet view tagged
// by accountId/accountLabel. Tokens are never round-tripped to the browser —
// GET /api/config only ever returns hasToken:true/false, never the token
// itself; a blank token field on save means "keep the existing one".
state._accountsUI = state._accountsUI || [];

async function loadAccountsUI() {
  if (!state.isRunningViaProxy) {
    const c = document.getElementById("accountsListContainer");
    if (c) c.innerHTML = '<div style="font-size:0.78rem; color:var(--text-secondary); padding:8px;">Multiple accounts require the local server (not available in static/offline mode).</div>';
    return;
  }
  try {
    const res = await fetch("/api/config");
    const cfg = await res.json();
    state._accountsUI = (cfg.accounts || []).map(a => ({
      ...a,
      _tokenInput: "",
      _watchlistIds: (a.watchlistId || '').split(',').map(w => w.trim()).filter(Boolean).concat(
        (a.watchlistId || '').trim() === '' ? [''] : []
      ),
    }));
    renderAccountsRows();
  } catch (err) {
    console.warn("[ACCOUNTS] Failed to load accounts:", err);
  }
}

function renderAccountsRows() {
  const container = document.getElementById("accountsListContainer");
  if (!container) return;
  if (state._accountsUI.length === 0) {
    container.innerHTML = '<div style="font-size:0.78rem; color:var(--text-secondary); padding:8px 2px;">No additional accounts yet. Click "+ Add Account" to sync a second (or third, or tenth) customer\'s Active IQ credentials alongside the one above.</div>';
    return;
  }
  // Ensure every account has at least one (possibly empty) watchlist input row visible.
  state._accountsUI.forEach(acct => {
    if (!acct._watchlistIds || acct._watchlistIds.length === 0) acct._watchlistIds = [''];
  });
  container.innerHTML = state._accountsUI.map((acct, i) => `
    <div style="display:flex; gap:8px; align-items:flex-start; padding:10px; border:1px solid var(--border-color); border-radius:var(--radius-sm); background:rgba(52,211,153,0.03); flex-wrap:wrap;">
      <div style="flex:1; min-width:140px;">
        <div class="form-helper" style="margin:0 0 3px;">Label</div>
        <input type="text" class="form-input" style="font-size:0.78rem; padding:6px 8px;" placeholder="Customer name" value="${(acct.label || '').replace(/"/g, '&quot;')}" oninput="state._accountsUI[${i}].label = this.value">
      </div>
      <div style="flex:1; min-width:200px;">
        <div class="form-helper" style="margin:0 0 3px;">Refresh Token ${acct.hasToken ? '<span style="color:#34d399;">(saved — leave blank to keep)</span>' : '<span style="color:#f59e0b;">(required)</span>'}</div>
        <input type="password" class="form-input" style="font-size:0.78rem; padding:6px 8px; font-family:var(--font-mono);" placeholder="${acct.hasToken ? '•••••••• (unchanged)' : 'Paste refresh token...'}" oninput="state._accountsUI[${i}]._tokenInput = this.value">
      </div>
      <div style="flex:1; min-width:180px;">
        <div class="form-helper" style="margin:0 0 3px;">Watchlist ID(s) (optional)</div>
        <div style="display:flex; flex-direction:column; gap:5px;">
          ${acct._watchlistIds.map((w, wi) => `
            <div style="display:flex; gap:5px; align-items:center;">
              <input type="text" class="form-input" style="font-size:0.78rem; padding:6px 8px; flex:1;" placeholder="Scope to a watchlist" value="${(w || '').replace(/"/g, '&quot;')}" oninput="state._accountsUI[${i}]._watchlistIds[${wi}] = this.value">
              <button class="action-btn secondary" style="font-size:0.7rem; padding:5px 8px; color:var(--status-critical); border-color:rgba(255,51,102,0.3);" onclick="_removeAccountWatchlistId(${i}, ${wi})" title="Remove this watchlist">✕</button>
            </div>
          `).join('')}
          <button class="action-btn secondary" style="font-size:0.7rem; padding:4px 8px; align-self:flex-start;" onclick="_addAccountWatchlistId(${i})">+ Add Watchlist</button>
        </div>
      </div>
      <div style="display:flex; align-items:center; gap:6px; padding-top:20px;">
        <label class="switch" style="transform:scale(0.8);">
          <input type="checkbox" ${acct.enabled !== false ? 'checked' : ''} onchange="state._accountsUI[${i}].enabled = this.checked">
          <span class="slider"></span>
        </label>
        <button class="action-btn secondary" style="font-size:0.7rem; padding:5px 9px; color:var(--status-critical); border-color:rgba(255,51,102,0.3);" onclick="removeAccountRow(${i})" title="Remove this account">✕</button>
      </div>
    </div>
  `).join("");
}

function addAccountRow() {
  state._accountsUI.push({ id: "", label: "", watchlistId: "", _watchlistIds: [''], enabled: true, hasToken: false, _tokenInput: "" });
  renderAccountsRows();
}

// Multiple watchlists per account: _watchlistIds is the editable array shown
// in the UI; watchlistId (comma-joined) stays the wire format the server
// already parses (_do_full_harvest splits account.watchlistId on ",") --
// only the editing surface changes, not the storage format.
function _addAccountWatchlistId(i) {
  state._accountsUI[i]._watchlistIds.push('');
  renderAccountsRows();
}

function _removeAccountWatchlistId(i, wi) {
  state._accountsUI[i]._watchlistIds.splice(wi, 1);
  if (state._accountsUI[i]._watchlistIds.length === 0) state._accountsUI[i]._watchlistIds.push('');
  renderAccountsRows();
}

function removeAccountRow(i) {
  state._accountsUI.splice(i, 1);
  renderAccountsRows();
}

async function saveAccountsUI() {
  const statusEl = document.getElementById("accountsSaveStatus");
  const missing = state._accountsUI.filter(a => !a.hasToken && !a._tokenInput.trim() && (a.label || "").trim());
  if (missing.length > 0) {
    if (statusEl) { statusEl.textContent = `⚠ "${missing[0].label}" needs a refresh token before saving.`; statusEl.style.color = "var(--status-critical)"; }
    return;
  }
  const payload = state._accountsUI
    .filter(a => (a.label || "").trim() || a._tokenInput.trim())
    .map(a => ({
      id: a.id || "",
      label: a.label || "",
      refreshToken: a._tokenInput || "",
      watchlistId: (a._watchlistIds || []).map(w => (w || '').trim()).filter(Boolean).join(','),
      enabled: a.enabled !== false,
    }));
  try {
    if (statusEl) { statusEl.textContent = "Saving…"; statusEl.style.color = "var(--text-secondary)"; }
    const res = await fetch("/api/config", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ accounts: payload }),
    });
    if (!res.ok) throw new Error(`Server returned ${res.status}`);
    if (statusEl) { statusEl.textContent = `✓ Saved ${payload.length} account(s). Sync to pull their fleets in.`; statusEl.style.color = "var(--status-normal)"; }
    await loadAccountsUI(); // reload so hasToken flags reflect what's actually stored
  } catch (err) {
    console.warn("[ACCOUNTS] Save failed:", err);
    if (statusEl) { statusEl.textContent = `⚠ Save failed: ${err.message}`; statusEl.style.color = "var(--status-critical)"; }
  }
}

async function saveSettings() {
  const mockToggle = document.getElementById("settingsMockModeToggle").checked;
  const refresh = document.getElementById("settingsRefreshToken").value.trim();
  const apiBaseInput = document.getElementById("settingsApiBaseUrl").value.trim() || "https://api.activeiq.netapp.com/v1";
  const intervalInput = parseInt(document.getElementById("settingsSyncInterval").value) || 0;
  const wlOnlyToggle   = document.getElementById("settingsWatchlistOnlyToggle").checked;
  const searchTermInput = (document.getElementById("settingsSearchTerm") ? document.getElementById("settingsSearchTerm").value : "").trim();
  const serialNumbersInput = (document.getElementById("settingsSerialNumbers") ? document.getElementById("settingsSerialNumbers").value : "").trim();
  const oldMockMode = state.mockMode;
  
  state.apiBaseUrl    = apiBaseInput;
  state.syncInterval  = intervalInput;
  state.watchlistOnly = wlOnlyToggle;
  state.searchTerm    = searchTermInput;
  state.serialNumbers = serialNumbersInput;
  
  safeSetItem("aiq_api_base_url",   apiBaseInput);
  safeSetItem("aiq_sync_interval",  intervalInput.toString());
  safeSetItem("aiq_watchlist_only", wlOnlyToggle ? "true" : "false");
  safeSetItem("aiq_search_term",    searchTermInput);
  safeSetItem("aiq_serial_numbers", serialNumbersInput);
  
  setMockMode(mockToggle);
  saveConfig(refresh, safeGetItem("aiq_access_token") || "", safeGetItem("aiq_token_expiry") || "");

  // Persist the refresh token to server-side aiq_config.json so that
  // the Python proxy (server.py) can read it for harvest requests.
  // The server reads from disk — not localStorage — so this POST is essential.
  if (state.isRunningViaProxy && refresh) {
    try {
        // Include all resolved watchlist IDs so the server can scope harvests across all watchlists
        const wlIds = state.watchlists && state.watchlists.length > 0
          ? state.watchlists.map(w => w.id).join(",")
          : (safeGetItem("aiq_watchlist_ids_text") || "").split(/[\n]+/).map(s => s.split("=").pop().trim()).filter(s => s.length > 5).join(",");
        const cfgRes = await fetch("/api/config", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ refreshToken: refresh, watchlistIds: wlIds })
      });
      if (cfgRes.ok) {
        console.log("[CONFIG] Refresh token persisted to server config.");
      } else {
        console.warn("[CONFIG] Server config save returned:", cfgRes.status);
      }
    } catch (err) {
      console.warn("[CONFIG] Could not persist token to server:", err);
    }
  }

  // Persist enrichment scanner settings to server
  await saveEnrichmentConfig();

  if (!mockToggle) {
    // Switching to live API mode: clear all mock data from state and localStorage
    // so stale mock systems don't persist across the mode switch
    state.systems = [];
    state.groups = [];
    state.watchlists = [];
    state.globalRisks = [];
    saveSystems();
    safeSetItem("aiq_custom_groups", "[]");
    safeSetItem("aiq_watchlists_db", "[]");
    console.log("[MODE] Cleared mock data, syncing live from API...");
    await loadProductionData(true);  // Force fresh harvest when switching from mock
    refreshUIState();
  } else if (mockToggle) {
    // Reset to mock systems database
    state.systems = MOCK_SYSTEMS.map(s => enrichSystemTelemetry(s));
    _resolveSnapMirrorPartners(state.systems);
    _inferClusterHA(state.systems);
    state.groups = [...DEFAULT_GROUPS];
    state.watchlists = [...MOCK_WATCHLISTS];
    state.globalRisks = [];
    saveSystems();
    safeSetItem("aiq_custom_groups", JSON.stringify(state.groups));
    saveWatchlists();
    if (state.systems.length > 0) {
      state.selectedSystem = state.systems[0];
    }
    refreshUIState();
  }
  
  alert("Settings saved successfully.");
  updateScheduledSyncInfo();
  switchTab("settings");
}

// ── Enrichment Scanner Controls ──────────────────────────────────────

async function triggerEnrichmentScan() {
  const statusText = document.getElementById("enrichStatusText");
  const statusLed = document.getElementById("enrichStatusLed");
  if (statusText) statusText.textContent = "Starting enrichment scan...";
  if (statusLed) statusLed.style.background = "#fbbf24";

  try {
    const res = await fetch("/api/enrich/scan", { method: "POST" });
    const data = await res.json();
    if (data.status === "started") {
      if (statusText) statusText.textContent = "Scan in progress — check status in ~60s...";
      if (statusLed) { statusLed.style.background = "#fbbf24"; statusLed.style.animation = "pulse 1.5s infinite"; }
      // Auto-refresh status after delay
      setTimeout(() => refreshEnrichmentStatus(), 5000);
      setTimeout(() => refreshEnrichmentStatus(), 30000);
      setTimeout(() => refreshEnrichmentStatus(), 90000);
    } else if (data.status === "already_running") {
      if (statusText) statusText.textContent = "Scan already in progress...";
    }
  } catch (err) {
    console.warn("[ENRICH] Scan trigger failed:", err);
    if (statusText) statusText.textContent = "Scan trigger failed — is the server running?";
    if (statusLed) statusLed.style.background = "#ef4444";
  }
}

async function refreshEnrichmentStatus() {
  const statusText = document.getElementById("enrichStatusText");
  const statusLed = document.getElementById("enrichStatusLed");
  const statusTime = document.getElementById("enrichStatusTime");

  try {
    const res = await fetch("/api/enrich/status");
    const data = await res.json();

    if (data.isRunning) {
      if (statusText) statusText.textContent = "Scan in progress...";
      if (statusLed) { statusLed.style.background = "#fbbf24"; statusLed.style.animation = "pulse 1.5s infinite"; }
      if (statusTime) statusTime.textContent = "";
    } else if (data.lastScan) {
      const lastDt = new Date(data.lastScan);
      const ageMs = Date.now() - lastDt.getTime();
      const ageH = Math.round(ageMs / 3600000);

      // Build summary from results
      const r = data.results || {};
      const parts = [];
      if (r.cisa_kev && r.cisa_kev.matched !== undefined) parts.push(`KEV: ${r.cisa_kev.matched} matched`);
      if (r.netapp_psirt && r.netapp_psirt.added !== undefined) parts.push(`PSIRT: +${r.netapp_psirt.added}`);
      if (r.nvd_netapp && r.nvd_netapp.new !== undefined) parts.push(`NVD: +${r.nvd_netapp.new}`);
      if (r.epss && r.epss.enriched !== undefined) parts.push(`EPSS: ${r.epss.enriched} scored`);
      if (r.knowledge_base && r.knowledge_base.new !== undefined) parts.push(`KB: +${r.knowledge_base.new}`);
      const summary = parts.length > 0 ? parts.join(" · ") : "No results yet";

      if (statusText) statusText.innerHTML = `<span style="color: var(--accent-green);">✓</span> Last scan: ${summary}`;
      if (statusLed) {
        statusLed.style.animation = "none";
        statusLed.style.background = ageH < 24 ? "#34d399" : ageH < 48 ? "#fbbf24" : "#ef4444";
      }
      if (statusTime) statusTime.textContent = ageH < 1 ? "< 1h ago" : `${ageH}h ago`;

      // Update interval selector from server
      if (data.intervalHours) {
        const sel = document.getElementById("settingsEnrichInterval");
        if (sel) sel.value = data.intervalHours.toString();
      }
    } else {
      if (statusText) statusText.textContent = data.enabled ? "Scanner active — waiting for first scan..." : "Scanner disabled";
      if (statusLed) { statusLed.style.background = data.enabled ? "#fbbf24" : "var(--text-muted)"; statusLed.style.animation = "none"; }
    }
  } catch (err) {
    // Not running via proxy, show offline status
    if (statusText) statusText.textContent = "Server not connected — start server.py for auto-enrichment";
    if (statusLed) { statusLed.style.background = "var(--text-muted)"; statusLed.style.animation = "none"; }
  }
}

async function saveEnrichmentConfig() {
  if (!state.isRunningViaProxy) return;
  try {
    const enrichEnabled = document.getElementById("settingsEnrichEnabled")?.checked ?? true;
    const enrichInterval = parseInt(document.getElementById("settingsEnrichInterval")?.value) || 12;
    const nvdApiKey = document.getElementById("settingsNvdApiKey")?.value?.trim() || "";
    const githubToken = document.getElementById("settingsGithubToken")?.value?.trim() || "";

    await fetch("/api/config", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ enrichEnabled, enrichIntervalHours: enrichInterval, nvdApiKey, githubToken })
    });
    console.log("[ENRICH] Config saved to server.");
  } catch (err) {
    console.warn("[ENRICH] Could not save enrichment config:", err);
  }
}

// ── Watchlist Import via ID Resolution ────────────────────────────────

// The Active IQ watchlist REST API requires session-based SSO auth that
// isn't available via the public developer API token.  Instead, users
// paste watchlist IDs (from the AIQ web UI URL bar) and we resolve the
// member systems via the GraphQL systems(watchlistId: "xxx") query.

async function resolveAndImportWatchlists() {
  const textarea = document.getElementById("settingsWatchlistIds");
  const status = document.getElementById("watchlistScopeStatus");
  if (!textarea) return;

  const raw = textarea.value.trim();
  if (!raw) {
    if (status) status.innerHTML = '<span style="color: var(--accent-amber);">⚠ Paste at least one watchlist ID in the text area above.</span>';
    return;
  }

  // Parse lines: "Name = ID" or just "ID"
  const entries = raw.split("\n").map(line => line.trim()).filter(Boolean).map(line => {
    const eqIdx = line.indexOf("=");
    if (eqIdx > 0) {
      return { name: line.substring(0, eqIdx).trim(), id: line.substring(eqIdx + 1).trim() };
    }
    return { name: line, id: line };
  }).filter(e => e.id.length > 5);

  if (entries.length === 0) {
    if (status) status.innerHTML = '<span style="color: var(--accent-amber);">⚠ No valid watchlist IDs found. Use format: Name = ID (one per line).</span>';
    return;
  }

  if (status) status.innerHTML = `<span style="color: var(--accent-amber);">⏳ Resolving ${entries.length} watchlist(s) via GraphQL...</span>`;

  // Resolve each watchlist by querying the server
  const resolved = [];
  for (const entry of entries) {
    try {
      if (status) status.innerHTML = `<span style="color: var(--accent-amber);">⏳ Resolving "${entry.name}"...</span>`;
      
      // Use the harvest endpoint with watchlistId to get just serial numbers
      const resp = await fetch(`/api/resolve-watchlist?watchlistId=${encodeURIComponent(entry.id)}&t=${Date.now()}`, {
        cache: "no-store"
      });
      const data = await resp.json();
      
      if (data.error) {
        console.warn(`[AIQ] Watchlist "${entry.name}" (${entry.id}) resolve failed:`, data.error);
        resolved.push({ id: entry.id, name: entry.name, systemSerials: [], error: data.error });
      } else {
        const serials = data.systemSerials || [];
        console.log(`[AIQ] Watchlist "${entry.name}" resolved: ${serials.length} systems`);
        resolved.push({ id: entry.id, name: entry.name, systemSerials: serials });
      }
    } catch (err) {
      console.error(`[AIQ] Watchlist "${entry.name}" resolve error:`, err);
      resolved.push({ id: entry.id, name: entry.name, systemSerials: [], error: err.message });
    }
  }

  // Store in state — MERGE new results into existing watchlists (don't replace)
  const successful = resolved.filter(w => w.systemSerials.length > 0);
  const failed = resolved.filter(w => w.systemSerials.length === 0);

  if (successful.length > 0) {
    // Merge: keep existing watchlists that aren't in this batch, then add/update the resolved ones
    const incomingIds = new Set(successful.map(w => w.id));
    const kept = state.watchlists.filter(w => !incomingIds.has(w.id));
    state.watchlists = [...kept, ...successful];
    saveWatchlists();
    // Also persist the full textarea text (all watchlists, including kept ones)
    const fullText = state.watchlists.map(w => `${w.name} = ${w.id}`).join("\n");
    safeSetItem("aiq_watchlist_ids_text", fullText);
    // Keep textarea in sync with the merged list
    if (textarea) textarea.value = fullText;

    // Push updated watchlist IDs to server config so /api/harvest uses them all
    if (state.isRunningViaProxy) {
      const allIds = state.watchlists.map(w => w.id).join(",");
      try {
        await fetch("/api/config", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ watchlistIds: allIds })
        });
      } catch (e) {
        console.warn("[AIQ] Could not push updated watchlist IDs to server:", e);
      }
    }

    renderSidebarGroups();

    const summary = successful.map(w => `${w.name} (${w.systemSerials.length})`).join(", ");
    let msg = `✅ Imported <strong>${successful.length}</strong> watchlist(s): ${summary}`;
    if (failed.length > 0) {
      msg += `<br><span style="color: var(--accent-amber);">⚠ ${failed.length} watchlist(s) had 0 systems (invalid ID?): ${failed.map(w => w.name).join(", ")}</span>`;
    }
    msg += `<br><span style="color: var(--accent-blue);">🔄 Syncing fleet data for new watchlist(s)…</span>`;
    if (status) status.innerHTML = msg;

    // Trigger a fresh harvest so the new watchlist's systems appear in the customer list
    await loadProductionData(true);

    const postSummary = state.watchlists.map(w => `${w.name} (${w.systemSerials.length})`).join(", ");
    if (status) status.innerHTML = `✅ Sync complete — ${state.watchlists.length} watchlist(s) active: ${postSummary}`;
  } else {
    if (status) status.innerHTML = '<span style="color: var(--accent-red);">❌ No watchlists resolved successfully. Check your IDs and try again.</span>';
  }
}

function clearImportedWatchlists() {
  state.watchlists = [];
  saveWatchlists();
  safeSetItem("aiq_watchlist_ids_text", "");
  const textarea = document.getElementById("settingsWatchlistIds");
  const status = document.getElementById("watchlistScopeStatus");
  if (textarea) textarea.value = "";
  if (status) status.innerHTML = 'Watchlists cleared. Showing all systems.';
  renderSidebarGroups();
}

function initWatchlistScope() {
  // Restore saved watchlist IDs text on page init
  const savedText = safeGetItem("aiq_watchlist_ids_text") || "";
  const textarea = document.getElementById("settingsWatchlistIds");
  if (textarea && savedText) textarea.value = savedText;
  
  // Restore saved watchlists from localStorage
  const savedWL = safeGetItem("aiq_watchlists_db");
  if (savedWL) {
    try {
      const parsed = JSON.parse(savedWL);
      if (Array.isArray(parsed) && parsed.length > 0 && parsed[0].systemSerials) {
        state.watchlists = parsed;
        const status = document.getElementById("watchlistScopeStatus");
        if (status) {
          const summary = parsed.map(w => `${w.name} (${w.systemSerials.length})`).join(", ");
          status.innerHTML = `📋 Active watchlists: ${summary}`;
        }
      }
    } catch (e) { /* ignore */ }
  }
}

async function updateApplicationCode() {
  if (window.location.protocol === "file:") {
    alert("Application Update Unavailable:\nUpdating code via Git is only supported when running the local Python server (server.py).\n\nIf you are running the dashboard as a file, please open a terminal in the folder and run 'git pull' manually.");
    return;
  }
  
  const btn = document.getElementById("appUpdateButton");
  if (!btn) return;
  const origText = btn.innerText;
  btn.disabled = true;
  btn.innerText = "Updating...";
  
  try {
    const response = await fetch("/api/app/update", { method: "POST" });
    const data = await response.json();
    if (response.ok && data.status === "success") {
      alert(`Success: ${data.message}`);
      window.location.reload();
    } else {
      throw new Error(data.message || "Failed to execute git update.");
    }
  } catch (err) {
    console.error("Update failed:", err);
    alert(`Update Failed:\n${err.message}\n\nEnsure that you have Git installed, the project directory is a valid git repository, and the local server is running with write permissions.`);
  } finally {
    btn.disabled = false;
    btn.innerText = origText;
  }
}

function updateScheduledSyncInfo() {
  const lastSyncEl = document.getElementById("syncLastTime");
  const nextSyncEl = document.getElementById("syncNextTime");
  
  if (!lastSyncEl || !nextSyncEl) return;
  
  if (!state.lastSync) {
    lastSyncEl.innerText = "Never Synced";
    lastSyncEl.style.color = "var(--text-secondary)";
  } else {
    lastSyncEl.innerText = new Date(state.lastSync).toLocaleString();
    lastSyncEl.style.color = "var(--text-primary)";
  }
  
  if (state.syncInterval === 0) {
    nextSyncEl.innerText = "Not Scheduled (Manual)";
    nextSyncEl.style.color = "var(--text-secondary)";
  } else {
    const lastTime = state.lastSync ? new Date(state.lastSync).getTime() : Date.now();
    const nextTime = new Date(lastTime + state.syncInterval * 60 * 60 * 1000);
    nextSyncEl.innerText = nextTime.toLocaleString();
    
    if (nextTime.getTime() < Date.now()) {
      nextSyncEl.style.color = "var(--status-warning)";
      nextSyncEl.innerText += " (Pending)";
    } else {
      nextSyncEl.style.color = "var(--status-normal)";
    }
  }
}

async function triggerManualSync() {
  const spinner = document.getElementById("syncSpinnerIcon");
  
  const mockToggle = document.getElementById("settingsMockModeToggle").checked;
  if (mockToggle) {
    alert("CORS/Offline Mode Warning:\nThe dashboard is currently in Offline Demo Mode. Please disable Offline Mode in settings and configure a valid Active IQ Developer Refresh Token to pull live REST telemetry.");
    return;
  }
  
  if (state.mockMode) {
    await saveSettings();
    return;
  }
  
  if (spinner) {
    spinner.style.animation = "spin 1s linear infinite";
  }
  
  try {
    await loadProductionData(true);  // Force refresh on manual sync
    state.lastSync = new Date().toISOString();
    safeSetItem("aiq_last_sync", state.lastSync);
    updateScheduledSyncInfo();
    refreshUIState();
    
    alert(`Successfully synchronized with Active IQ!\n\nAll required metrics and data points collected:\n✓ System inventory & telemetry\n✓ Active predictive risk signatures\n✓ Multi-hop firmware/OS path plans\n✓ Contracts & warranty lifecycles\n✓ Switch fabric configuration states\n✓ Hypervisor integrations\n✓ Support cases & action items\n\nDashboard has been updated.`);
  } catch (err) {
    console.error("Manual sync failed:", err);
    alert(`Active IQ API Synchronization Failed:\n${err.message}\n\nRefer to CORS console logs or settings documentation for assistance.`);
  } finally {
    if (spinner) {
      spinner.style.animation = "";
    }
  }
}

async function checkAutoSync() {
  if (state.mockMode || state.syncInterval === 0) return;
  
  const lastTime = state.lastSync ? new Date(state.lastSync).getTime() : 0;
  const intervalMs = state.syncInterval * 60 * 60 * 1000;
  
  if (Date.now() - lastTime >= intervalMs) {
    console.log('[AIQ] Auto-sync interval reached — polling Active IQ API...');
    try {
      await loadProductionData();
      state.lastSync = new Date().toISOString();
      safeSetItem('aiq_last_sync', state.lastSync);
      updateScheduledSyncInfo();
      refreshUIState();
      // Also refresh advisory DB on schedule (non-blocking)
      setTimeout(() => loadDynamicBulletins(), 2000);
      console.log('[AIQ] Auto-sync complete.');
    } catch (err) {
      console.error('[AIQ] Auto-sync failed:', err);
    }
  }
}

// Start auto-sync checking timer
setInterval(checkAutoSync, 60000); // Check every 60 seconds

// ── manualRefresh ─────────────────────────────────────────────────────────────
// Triggered by the Refresh button in the top header bar.
// Force-pulls live data from the AIQ API (bypasses server cache), re-syncs all
// enrichment sources, invalidates every memo/dirty cache, then re-renders the
// current tab exactly in-place (no tab switch, scroll position preserved).
async function manualRefresh() {
  const btn  = document.getElementById('manualRefreshBtn');
  const icon = document.getElementById('refreshBtnIcon');
  const text = document.getElementById('refreshBtnText');

  // ── Visual: enter loading state ──────────────────────────────────────────
  if (btn)  { btn.disabled = true; btn.style.opacity = '0.65'; btn.style.cursor = 'not-allowed'; }
  if (icon) { icon.style.animation = 'spin 0.8s linear infinite'; icon.style.transformOrigin = 'center'; }
  if (text) { text.textContent = 'Refreshing…'; }

  // ── Capture current scroll position so we can restore it after render ────
  const mainContent = document.querySelector('.main-content');
  const scrollY = mainContent ? mainContent.scrollTop : 0;

  // ── Bust all memo caches — fresh data must flow through every guard ───────
  _gfsKeyIncl = null; _gfsResIncl = null;
  _gfsKeyExcl = null; _gfsResExcl = null;
  _chartDataStamp  = null;
  _selectorStamp   = null;
  _sidebarStamp    = null;
  _upgradePathCache.clear();

  try {
    // 1. Force pull from Active IQ API (force=1 bypasses server-side cache)
    await loadProductionData(true);

    // 2. Re-sync enrichment engine — CVE data, version mapping, vulnerability info
    //    Runs non-blocking via setTimeout so it never stalls the UI thread
    setTimeout(() => enrichmentEngine.syncFromServer(state.systems), 400);

    // 3. Reload security advisory DB from server (non-blocking — fires after render)
    //    This refreshes the "X versions · Y CVEs" badge in the header and all
    //    advisory panels without slowing down the main refresh response.
    setTimeout(() => loadDynamicBulletins(), 1500);

    // 4. Re-render current tab in-place — switches to same tab (no visual jump)
    //    refreshUIState() calls switchTab(state.activeTab || 'overview') which
    //    just re-renders without navigating away
    refreshUIState();

    console.log('[AIQ] Manual refresh complete.');
  } catch (err) {
    console.error('[AIQ] Manual refresh failed:', err);
  } finally {
    // ── Restore scroll position (rAF ensures DOM has settled first) ──────────
    if (mainContent) {
      requestAnimationFrame(() => { mainContent.scrollTop = scrollY; });
    }

    // ── Restore button to idle state ─────────────────────────────────────────
    if (btn)  { btn.disabled = false; btn.style.opacity = ''; btn.style.cursor = ''; }
    if (icon) { icon.style.animation = ''; }
    if (text) { text.textContent = 'Refresh'; }
  }
}


function updateStatusIndicators() {
  const indicators = document.querySelectorAll(".indicator");
  const textLabel = document.getElementById("connectionStatusText");
  const { refresh } = loadConfig();
  const hasLiveData = state.systems?.some(s => s._source === 'graphql');

  indicators.forEach(ind => {
    ind.className = "indicator";
    if (hasLiveData) {
      ind.classList.add("connected");
      if (textLabel) textLabel.innerText = "API Connected";
    } else if (state.mockMode) {
      ind.classList.add("mock");
      if (textLabel) textLabel.innerText = "Mock Server Mode";
    } else if (refresh) {
      ind.classList.add("connected");
      if (textLabel) textLabel.innerText = "API Connected";
    } else {
      ind.classList.add("disconnected");
      if (textLabel) textLabel.innerText = "No Credentials Configured";
    }
  });
}

function refreshUIState() {
  // 1. Redraw sidebar groups and filter menus
  renderSidebarGroups();
  
  // 2. Validate and adjust current selected system reference
  if (state.systems && state.systems.length > 0) {
    const exists = state.systems.some(s => s.serialNumber === (state.selectedSystem ? state.selectedSystem.serialNumber : ""));
    if (!exists) {
      state.selectedSystem = state.systems[0];
    }
  }

  // 3. Rebuild global search parameters
  updateSearchSuggestions();

  // 4. Invalidate TAM dirty-stamp caches so a data refresh always forces a
  //    full re-render of all sections, even when serial selection is unchanged.
  renderTAMTab._lastFP = null;
  if (typeof renderNodeVisualLayout === 'function') renderNodeVisualLayout._lastFP = null;

  // 5. Force redraw layout of the active tab view
  if (state.currentTab) {
    switchTab(state.currentTab);
  } else if (state.activeTab) {
    switchTab(state.activeTab);
  } else {
    switchTab("overview");
  }
}

// ── First-run setup banner ────────────────────────────────────────────────────
// Shown when no Active IQ credentials are configured (needsSetup: true from server).
